{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6C5CE7;--muted:#6b7280;--bg:#0f1724;--card:#0b1220;--glass:rgba(255,255,255,0.04);--white:#eef2ff}
    html,body{height:100%;margin:0;font-family:Inter,ui-sans-serif,system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;color:var(--white);background:linear-gradient(180deg,#071028 0%, #071731 60%), url('assets/img/pattern.svg');background-size:600px;}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#00b4d8);display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{color:rgba(238,242,255,0.85);text-decoration:none;margin-left:18px;font-weight:600}
    .hero{padding:56px 28px;display:grid;grid-template-columns:1fr 420px;gap:32px;align-items:start}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:14px;box-shadow:0 6px 30px rgba(2,6,23,0.6)}
    h1{margin:0 0 8px 0;font-size:28px;letter-spacing:-0.02em}
    p.lead{color:var(--muted);margin:0 0 16px 0}
    .cta{display:inline-block;padding:10px 16px;border-radius:10px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    .subtle{color:var(--muted);font-size:13px}
    /* Proof gallery */
    .proof{margin-top:18px}
    .testimonial{min-height:110px;display:flex;flex-direction:column;gap:8px}
    .quote{font-style:italic;color:#e7eaf6}
    .who{color:var(--muted);font-size:13px}
    .badges{display:flex;gap:10px;align-items:center;margin-top:12px}
    .badge{width:48px;height:48px;border-radius:10px;background:var(--glass);display:flex;align-items:center;justify-content:center;position:relative;cursor:default}
    .badge svg{width:22px;height:22px;fill:var(--accent)}
    .tooltip{position:absolute;bottom:60px;left:50%;transform:translateX(-50%) scale(0.95);background:#061024;padding:8px 10px;border-radius:8px;color:var(--white);font-size:13px;opacity:0;pointer-events:none;transition:200ms ease;white-space:nowrap}
    .badge:hover .tooltip{opacity:1;transform:translateX(-50%) scale(1)}
    /* small footer */
    footer{padding:22px 28px;color:var(--muted);font-size:13px}
    /* responsive */
    @media(max-width:880px){.hero{grid-template-columns:1fr;padding:28px;}.panel{padding:18px}}
  </style>
</head>
<body>
<header>
  <div class="brand">
    <div class="logo">M</div>
    <div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
      <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}} — Clinical Practice</div>
    </div>
  </div>
  <nav>
    <a href="index.html">Home</a>
    <a href="about.html">Story</a>
    <a href="specialties.html">Offerings</a>
    <a href="fees.html">Rates</a>
    <a href="book.html">Book</a>
    <a href="contact.html">Connect</a>
  </nav>
</header>
<main>
  <section class="hero">
    <div class="panel">
      <h1>A little about the room I hold</h1>
      <p class="lead">I offer focused, clinical sessions for people navigating change, overwhelm, and next-step decisions. My work blends practical structure with reflective space so you can leave a session with a clear, usable step forward.</p>
      <p class="subtle">I work with adults across transitions — career shifts, relationships, and the recurring patterns that shape your days. I bring training in evidence-informed approaches and a curiosity-first, nonjudgmental stance.</p>
      <div style="margin-top:16px">
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <span style="margin-left:12px;color:var(--muted);font-size:13px">or <a href="contact.html" style="color:var(--accent);text-decoration:none">send a note</a></span>
      </div>
      <div style="margin-top:18px;color:var(--muted);font-size:13px">Sessions are confidential. I do not provide emergency services; if you are in crisis, please contact local emergency services or a crisis line.</div>
    </div>

    <aside class="panel">
      <div style="font-size:13px;color:var(--muted);margin-bottom:8px">Clinical snapshot</div>
      <div style="font-weight:700;font-size:20px">Care philosophy &mdash; steady curiosity</div>
      <div style="margin-top:12px;color:var(--muted);font-size:14px">Meeting you where your life is now: concrete tools, a few reliably held questions, and a way to notice small shifts. Therapy is collaborative; I offer structure without scripts.</div>

      <div class="proof">
        <div style="font-size:13px;color:var(--muted)">Proof Gallery</div>
        <div id="testimonial" class="testimonial" aria-live="polite" style="margin-top:8px">
          <div class="quote" id="quote">"The sessions helped me make a tangible plan, and I felt heard without feeling hurried."</div>
          <div class="who" id="who">— C., 34, project manager</div>
        </div>
        <div class="badges">
          <div class="badge" data-tip="Licensed clinician, MA in Counseling">
            <svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zm0 11a5 5 0 100 10 5 5 0 000-10z"/></svg>
            <div class="tooltip">Licensed clinician, MA in Counseling</div>
          </div>
          <div class="badge" data-tip="12+ years in adult therapy">
            <svg viewBox="0 0 24 24"><path d="M12 2a10 10 0 100 20 10 10 0 000-20zM7 11l3 3 7-7"/></svg>
            <div class="tooltip">12+ years in adult therapy</div>
          </div>
          <div class="badge" data-tip="Training in evidence-informed methods">
            <svg viewBox="0 0 24 24"><path d="M3 12l2-2 4 4 8-8 2 2-10 10L3 12z"/></svg>
            <div class="tooltip">Training in evidence-informed methods</div>
          </div>
        </div>
        <div style="margin-top:10px;color:var(--muted);font-size:13px">Hover a badge for more. Testimonials rotate automatically.</div>
      </div>
    </aside>
  </section>

  <section style="padding:28px;display:flex;gap:22px;flex-wrap:wrap">
    <div class="panel" style="flex:1;min-width:280px">
      <h3 style="margin-top:0">Limits & boundaries</h3>
      <p class="subtle">I maintain clear boundaries around session length, communication, and record-keeping. I will explain confidentiality in our first meeting and the legal limits to confidentiality (e.g., risk of harm, subpoenas). I keep secure records and share summaries only with your written consent.</p>
    </div>
    <div class="panel" style="flex:1;min-width:280px">
      <h3 style="margin-top:0">Scope and suitability</h3>
      <p class="subtle">I offer time-limited intensives and short series focused on concrete goals. If you need ongoing or complex crisis services, I will help connect you with appropriate community resources and longer-term care. My practice is for adults; I do not provide services for minors or court-ordered evaluations here.</p>
    </div>
  </section>

</main>
<footer>
  <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
    <div style="max-width:640px">Appointments by request in {{CITY}}, {{STATE}}. For scheduling: <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a>.</div>
    <div style="margin-top:8px"><a href="book.html" style="color:var(--accent);text-decoration:none">Book a conversation</a></div>
  </div>
</footer>

<script>
// Proof gallery rotation
(function(){
  const items = [
    {q:'"I left sessions with one clear next step and felt lighter—practical and quiet at once."', who:'— A., 29, teacher'},
    {q:'"The mapping questions helped me see a pattern and try a small experiment the following week."', who:'— R., 41, parent'},
    {q:'"I needed straightforward thinking and I received a calm, structured approach."', who:'— S., 36, designer'}
  ];
  let i=0; const quoteEl=document.getElementById('quote'); const whoEl=document.getElementById('who');
  function show(){
    const item=items[i];
    quoteEl.style.opacity=0; whoEl.style.opacity=0;
    setTimeout(()=>{ quoteEl.textContent=item.q; whoEl.textContent=item.who; quoteEl.style.opacity=1; whoEl.style.opacity=1; },260);
    i=(i+1)%items.length;
  }
  setInterval(show,6000);
})();
// Badge tooltips already handled with CSS hover
</script>
</body>
</html>"} 
