<body>
<header>
  <div style="display:flex;gap:14px;align-items:center">
    <div class="logo">P</div>
    <div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
      <div style="font-size:12px;color:var(--muted)">Programs & clinical focus</div>
    </div>
  </div>
  <nav>
    <a href="index.html">Base</a>
    <a href="approach.html">Method</a>
    <a href="specialties.html">Services</a>
    <a href="fees.html">Fees</a>
    <a href="book.html">Reserve</a>
  </nav>
</header>
<main class="wrap">
  <div class="grid">
    <div>
      <div class="card">
        <h1>Focused help, framed around your aim</h1>
        <p class="muted">Here are structured programs I offer. Toggle between a monthly subscription-style rhythm and single-package pricing to compare what fits your needs.</p>

        <div class="comparator" id="comparator">
          <div style="font-size:13px;color:var(--muted)">View prices as</div>
          <div class="toggle" role="tablist">
            <div class="opt active" data-mode="monthly">Monthly</div>
            <div class="opt" data-mode="package">Package</div>
          </div>

          <div class="plans" id="plans">
            <div class="plan">
              <div>
                <div style="font-weight:700">Clarity Sprint</div>
                <div class="desc">3 focused sessions for a pressing decision</div>
              </div>
              <div class="price"><span class="num" data-monthly="420" data-package="1150">$420</span><span style="font-size:13px;color:var(--muted)">/mo</span></div>
            </div>

            <div class="plan">
              <div>
                <div style="font-weight:700">Transition Series</div>
                <div class="desc">Six sessions for role or relational shifts</div>
              </div>
              <div class="price"><span class="num" data-monthly="320" data-package="1750">$320</span><span style="font-size:13px;color:var(--muted)">/mo</span></div>
            </div>

            <div class="plan">
              <div>
                <div style="font-weight:700">Anchor Package</div>
                <div class="desc">Ongoing short-check rhythm for steady work</div>
              </div>
              <div class="price"><span class="num" data-monthly="220" data-package="1200">$220</span><span style="font-size:13px;color:var(--muted)">/mo</span></div>
            </div>
          </div>
        </div>

        <div style="margin-top:16px;color:var(--muted);font-size:13px">Monthly view expresses a recurring cadence; package view shows the bulk price if you prefer a set of sessions paid up front. No promises—just clear options to pick from.</div>
      </div>

      <div class="card" style="margin-top:14px">
        <h3 style="margin-top:0">Who I usually work with</h3>
        <p class="muted">Adults navigating role change, parents balancing identities, folks hoping to interrupt a pattern. I focus on practical momentum: experiments, tracking, and short-term pivots.</p>
      </div>
    </div>

    <aside class="card">
      <div style="font-weight:700">Quick comparison</div>
      <div style="margin-top:10px;color:var(--muted);font-size:14px">If you want a single, directional push, Clarity Sprint often helps. If you want scaffolding across weeks, consider the Transition Series. I can help you decide in a short consult.</div>
      <div style="margin-top:14px">
        <a href="{{PRIMARY_CTA_URL}}" style="display:inline-block;padding:10px 14px;background:var(--accent);color:#071023;border-radius:10px;font-weight:800;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a>
      </div>
      <div style="margin-top:14px;color:var(--muted);font-size:13px">Sessions are confidential. Not a crisis service. If you are in immediate danger, contact emergency services.</div>
    </aside>
  </div>
</main>
<footer>
  <div style="padding:10px 28px;color:var(--muted);font-size:13px">Email: <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> • Call: <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a></div>
</footer>

<script>
// Pricing comparator logic with animated numbers
(function(){
  const opts=document.querySelectorAll('.opt');
  const nums=document.querySelectorAll('.num');
  let mode='monthly';
  function animateValue(el, start, end, duration){
    const startTime=performance.now();
    function loop(now){
      const t=Math.min(1,(now-startTime)/duration);
      const value=Math.round(start + (end-start)*t);
      el.textContent = '$' + value;
      if(t<1) requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
  opts.forEach(o=>o.addEventListener('click', ()=>{
    opts.forEach(x=>x.classList.remove('active'));
    o.classList.add('active');
    mode=o.dataset.mode;
    nums.forEach(n=>{
      const from = parseInt(n.textContent.replace(/[^0-9]/g,'')) || 0;
      const to = parseInt(n.dataset[mode]);
      animateValue(n, from, to, 550);
      // suffix
      setTimeout(()=>{
        const suffix = mode==='monthly'?'/mo':' total';
        n.nextSibling.textContent = mode==='monthly'?'/mo':' total';
      },560);
    });
  }));
  // initialize numeric suffixes
  nums.forEach(n=>{ n.nextSibling.textContent='/mo'; });
})();
</script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071217;--card:#071525;--accent:#8CE99A;--muted:#9fb0c9;--white:#ecf9f3}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#02121b 0%, #071225 100%), url('assets/img/pattern.svg');color:var(--white)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;background:rgba(255,255,255,0.02)}
    .logo{width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,#70ffb2,var(--accent));display:flex;align-items:center;justify-content:center;font-weight:800}
    nav a{color:var(--white);text-decoration:none;margin-left:16px;font-weight:600}
    .container{padding:28px}
    .cols{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .card{background:var(--card);padding:18px;border-radius:12px}
    h1{margin:0 0 10px 0}
    .muted{color:var(--muted)}
    .process{display:flex;flex-direction:column;gap:12px;margin-top:14px}
    .step{display:flex;gap:12px;align-items:flex-start}
    .num{width:36px;height:36px;border-radius:8px;background:rgba(255,255,255,0.03);display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--accent)}
    /* Pricing comparator — different labels + animated */
    .comparator{margin-top:12px;padding-top:8px;border-top:1px dashed rgba(255,255,255,0.03)}
    .modes{display:flex;gap:8px;margin-bottom:10px}
    .chip{padding:8px 10px;border-radius:999px;background:rgba(255,255,255,0.02);cursor:pointer;font-weight:700}
    .chip.active{background:linear-gradient(90deg,rgba(140,233,154,0.12),rgba(140,233,154,0.04));color:var(--white)}
    .packages{display:flex;flex-direction:column;gap:10px}
    .pkg{display:flex;justify-content:space-between;align-items:center;padding:10px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)}
    .pkg .title{font-weight:800}
    .pkg .price{font-weight:900;color:var(--accent)}
    footer{padding:16px 28px;color:var(--muted)}
    @media(max-width:880px){.cols{grid-template-columns:1fr}}
  </style>
</head>
<body>
<header>
  <div style="display:flex;gap:14px;align-items:center">
    <div class="logo">A</div>
    <div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
      <div style="font-size:12px;color:var(--muted)">Clinical approach & session flow</div>
    </div>
  </div>
  <nav>
    <a href="index.html">Welcome</a>
    <a href="specialties.html">Services</a>
    <a href="about.html">Who I am</a>
    <a href="book.html">Meet</a>
    <a href="contact.html">Reach</a>
  </nav>
</header>
<main class="container">
  <div class="cols">
    <div>
      <div class="card">
        <h1>How work usually looks</h1>
        <p class="muted">I mix direct assessment, simple tools, and reflective questions. Sessions are held with clarity and openness—less layering, more pruning. Below is a sketch of common steps.</p>

        <div class="process">
          <div class="step"><div class="num">1</div><div><div style="font-weight:700">Clarify</div><div class="muted">We name the immediate problem and what success would look like.</div></div></div>
          <div class="step"><div class="num">2</div><div><div style="font-weight:700">Map</div><div class="muted">Identify patterns and small levers you can try between sessions.</div></div></div>
          <div class="step"><div class="num">3</div><div><div style="font-weight:700">Try</div><div class="muted">Put a short experiment in place, with a concrete observation plan.</div></div></div>
          <div class="step"><div class="num">4</div><div><div style="font-weight:700">Reflect</div><div class="muted">Review what changed, and refine the next step.</div></div></div>
        </div>

        <div style="margin-top:14px;color:var(--muted);font-size:13px">I aim for sessions that leave you with one clear, achievable next move. If long-term work is needed, we'll discuss a rhythm that supports growth without overwhelm.</div>

        <div class="comparator" id="comp2">
          <div style="font-weight:700">Price glance</div>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Choose how you want to pay: single deep sessions or short bundles.</div>

          <div class="modes" style="margin-top:8px">
            <div class="chip active" data-mode="single">Single Sessions</div>
            <div class="chip" data-mode="bundle">Short Bundles</div>
          </div>

          <div class="packages" id="packages">
            <div class="pkg">
              <div>
                <div class="title">Deep One</div>
                <div class="muted" style="font-size:13px">90-minute focused session</div>
              </div>
              <div class="price"><span class="val" data-single="210" data-bundle="190">$210</span></div>
            </div>
            <div class="pkg">
              <div>
                <div class="title">Three-Notes Arc</div>
                <div class="muted" style="font-size:13px">Three sessions spaced over 4–6 weeks</div>
              </div>
              <div class="price"><span class="val" data-single="180" data-bundle="500">$180</span></div>
            </div>
            <div class="pkg">
              <div>
                <div class="title">Steady Check</div>
                <div class="muted" style="font-size:13px">Monthly short check-ins (three months)</div>
              </div>
              <div class="price"><span class="val" data-single="140" data-bundle="370">$140</span></div>
            </div>
          </div>
        </div>

      </div>

      <div class="card" style="margin-top:12px">
        <h3 style="margin-top:0">Confidentiality & boundaries</h3>
        <p class="muted">Conversations are confidential within legal limits. I keep records for clinical and scheduling purposes. I am not an on-call crisis service; for urgent safety concerns, please contact emergency services or your local crisis line.</p>
      </div>
    </div>

    <aside class="card">
      <div style="font-weight:800">A short note on fit</div>
      <div style="margin-top:10px;color:var(--muted);font-size:14px">If you’re seeking immediate crisis care or forensic evaluations, I will help refer you. If you want pragmatic, clinically grounded work focused on realistic changes, we may be a good match.</div>
      <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" style="display:inline-block;padding:10px 12px;background:var(--accent);color:#042016;border-radius:10px;text-decoration:none;font-weight:800">{{PRIMARY_CTA_LABEL}}</a></div>
      <div style="margin-top:14px;color:var(--muted);font-size:13px">I respond to booking inquiries within a few business days. Please include availability in your initial message to speed scheduling.</div>
    </aside>
  </div>
</main>
<footer>
  <div style="padding:12px 28px;color:var(--muted);font-size:13px">Not an emergency service. Confidential practice in {{CITY}}, {{STATE}}. Contact: <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a></div>
</footer>

<script>
// Comparator for approach page with smooth number transitions
(function(){
  const chips=document.querySelectorAll('.chip');
  const vals=document.querySelectorAll('.val');
  function animateNum(el, start, end, dur){
    const sTime=performance.now();
    function frame(now){
      const t=Math.min(1,(now-sTime)/dur);
      const cur=Math.round(start + (end-start)*t);
      el.textContent = '$'+cur;
      if(t<1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }
  chips.forEach(c=>c.addEventListener('click', ()=>{
    chips.forEach(x=>x.classList.remove('active'));
    c.classList.add('active');
    const mode=c.dataset.mode; // 'single' or 'bundle'
    vals.forEach(v=>{
      const from = parseInt(v.textContent.replace(/[^0-9]/g,'')) || 0;
      const to = parseInt(v.dataset[mode]);
      animateNum(v, from, to, 420);
    });
  }));
  // initialize displays
  vals.forEach(v=>{ v.textContent = '$' + v.dataset.single; });
})();
</script>
